using namespace tigersheets;
bool movesResultArray(QCoreApplication& app){std::atomic<std::uintptr_t> produced{0};bool done=false,same=false;CalculationScheduler scheduler([&](const Json& book){Json result={{"revision",book.at("revision")},{"status","ok"},{"values",Json::array({{{"sheet","s"},{"row",1},{"col",1},{"type","number"},{"value",42}}})}};produced=reinterpret_cast<std::uintptr_t>(result.at("values").get_ref<const Json::array_t&>().data());return result;});scheduler.onResult=[&](Json value){same=reinterpret_cast<std::uintptr_t>(value.at("values").get_ref<const Json::array_t&>().data())==produced.load();done=true;};scheduler.request({{"revision",5}});QElapsedTimer timer;timer.start();while(!done&&timer.elapsed()<3000)app.processEvents();if(!done||!same){std::cerr<<"FAILED: worker calculation arrays must transfer into an owning UI callback without a full JSON clone\n";return false;}return true;}
bool preparesDisplayValues(QCoreApplication& app){
 WorkbookSession session;const std::vector<std::string> inputs={"'=AVG(A1:A2)","'00123","TRUE","#DIV/0!","","'"};Json ops=Json::array();for(std::size_t row=0;row<inputs.size();++row)ops.push_back({{"type","set_cell"},{"sheet","sheet-1"},{"row",row+1},{"col",1},{"input",inputs[row]}});ops.push_back({{"type","set_cell"},{"sheet","sheet-1"},{"row",1},{"col",2},{"input","=1+1"}});if(!session.apply(0,ops))return false;Json result;
 CalculationScheduler scheduler([&](const Json& book){Json values=Json::array();const std::vector<Json> typed={Json("=AVG(A1:A2)"),Json("00123"),Json(true),Json("#DIV/0!"),Json(),Json("")};const std::vector<std::string> types={"string","string","boolean","error","blank","string"};for(std::size_t row=0;row<typed.size();++row)values.push_back({{"sheet","sheet-1"},{"row",row+1},{"col",1},{"type",types[row]},{"value",typed[row]}});values.push_back({{"sheet","sheet-1"},{"row",1},{"col",2},{"type","number"},{"value",2}});values.push_back({{"sheet","sheet-1"},{"row",2},{"col",2},{"type","number"},{"value",3}});return Json{{"revision",book.at("revision")},{"status","ok"},{"values",std::move(values)}};});scheduler.onResult=[&](Json value){result=std::move(value);};scheduler.request(session.snapshot());QElapsedTimer timer;timer.start();while(result.is_null()&&timer.elapsed()<3000)app.processEvents();if(result.is_null()||!result.contains("displayValues")||result.at("displayValues").size()!=3||result.at("values").size()!=8){std::cerr<<"FAILED: worker must publish a compact formula/spill display cache while retaining complete typed calculation values\n";return false;}
 WorksheetModel model(session);model.setCalculated(result);if(model.data(model.index(0,1)).toString()!="2"||model.data(model.index(1,1)).toString()!="3"){std::cerr<<"FAILED: compact display cache must render formula and spill cells\n";return false;}const auto clip=model.copyRange(0,0,5,0);if(!model.pasteRange(0,3,clip,"values")){std::cerr<<"FAILED: compact cache must retain typed literal Paste Values\n";return false;}const auto calculated=CalculationEngine().calculate(session.snapshotView());int found=0;for(const auto& value:calculated.at("values"))if(value.at("col")==4){const int row=value.at("row");if(value.at("type")!=std::vector<std::string>{"text","text","boolean","error","empty","text"}.at(row-1)||value.at("value")!=std::vector<Json>{Json("=AVG(A1:A2)"),Json("00123"),Json(true),Json("#DIV/0!"),Json(),Json("")}.at(row-1)){std::cerr<<"FAILED: compact display cache changed literal text/Boolean/error types: "<<value.dump()<<"\n";return false;}++found;}if(found!=6||!model.raw(4,3).isEmpty())return false;return true;
}
bool preservesParsedLiterals(QCoreApplication& app){WorkbookSession session;session.apply(0,Json::array({{{"type","set_cell"},{"sheet","sheet-1"},{"row",1},{"col",1},{"input","25%"}},{{"type","set_cell"},{"sheet","sheet-1"},{"row",2},{"col",1},{"input","true"}}}));Json result;CalculationScheduler scheduler;scheduler.onResult=[&](Json value){result=std::move(value);};scheduler.request(session.snapshot());QElapsedTimer timer;timer.start();while(result.is_null()&&timer.elapsed()<3000)app.processEvents();WorksheetModel model(session);model.setCalculated(result);if(model.data(model.index(0,0)).toString()!="0.25"||model.data(model.index(1,0)).toString()!="TRUE"){std::cerr<<"FAILED: compact caches must preserve parsed percentage and Boolean display semantics\n";return false;}return true;}
bool preservesErrorSort(QCoreApplication& app){WorkbookSession session;session.apply(0,Json::array({{{"type","set_cell"},{"sheet","sheet-1"},{"row",1},{"col",1},{"input","#DIV/0!"}},{{"type","set_cell"},{"sheet","sheet-1"},{"row",2},{"col",1},{"input","z"}}}));Json result;CalculationScheduler scheduler;scheduler.onResult=[&](Json value){result=std::move(value);};scheduler.request(session.snapshot());QElapsedTimer timer;timer.start();while(result.is_null()&&timer.elapsed()<3000)app.processEvents();WorksheetModel model(session);model.setCalculated(result);if(!model.sortRange(0,0,1,0,true)||model.raw(0,0)!="z"){std::cerr<<"FAILED: compact caches must retain error type for financial row sorting\n";return false;}return true;}
bool preparesCharts(QCoreApplication& app){WorkbookSession session;session.apply(0,Json::array({{{"type","set_cell"},{"sheet","sheet-1"},{"row",1},{"col",1},{"input","Quarter"}},{{"type","set_cell"},{"sheet","sheet-1"},{"row",1},{"col",2},{"input","=\"Revenue\""}},{{"type","set_cell"},{"sheet","sheet-1"},{"row",2},{"col",1},{"input","=\"Q1\""}},{{"type","set_cell"},{"sheet","sheet-1"},{"row",2},{"col",2},{"input","=25"}}}));auto book=session.snapshot();Json chart={{"id","forecast"},{"sheet","sheet-1"},{"type","column"},{"title","Revenue"},{"range",{{"row1",1},{"col1",1},{"row2",2},{"col2",2}}}};auto invalid=chart;invalid["id"]="invalid";invalid["range"]["row2"]=10002;book["charts"]=Json::array({chart,invalid});Json result;CalculationScheduler scheduler;scheduler.onResult=[&](Json value){result=std::move(value);};scheduler.request(std::move(book));QElapsedTimer timer;timer.start();while(result.is_null()&&timer.elapsed()<3000)app.processEvents();if(!result.contains("preparedCharts")||!result.at("preparedCharts").contains("forecast")||!result.at("preparedCharts").contains("invalid")){std::cerr<<"FAILED: calculation worker must prepare bounded chart data and chart-specific diagnostics before UI delivery\n";return false;}const auto& data=result.at("preparedCharts").at("forecast").at("data");if(data.at("categories")[0]!="Q1"||data.at("series")[0].at("name")!="Revenue"||data.at("series")[0].at("values")[0]!=25||!result.at("preparedCharts").at("invalid").contains("error")){std::cerr<<"FAILED: prepared charts must preserve calculated labels and report invalid ranges independently\n";return false;}return true;}
int main(int argc,char**argv){
 QCoreApplication app(argc,argv);if(!movesResultArray(app)||!preservesErrorSort(app)||!preparesDisplayValues(app)||!preservesParsedLiterals(app)||!preparesCharts(app))return 1;QSemaphore started,release;Json result;int delivered=0;
 CalculationScheduler scheduler([&](const Json& book){if(book["revision"]==1){started.release();release.acquire();}return Json{{"revision",book["revision"]},{"status","completed"}};});
 scheduler.onResult=[&](const Json& value){result=value;++delivered;};
 scheduler.request({{"revision",1}});if(!started.tryAcquire(1,3000)){std::cerr<<"FAILED: worker starts\n";return 1;}
 scheduler.request({{"revision",2}});release.release();QElapsedTimer deadline;deadline.start();while(delivered==0&&deadline.elapsed()<3000)app.processEvents();
 if(delivered!=1||result["revision"]!=2){std::cerr<<"FAILED: asynchronous calculation discards stale results\n";return 1;}
 scheduler.request({{"revision",3}});scheduler.cancel();deadline.restart();while(deadline.elapsed()<50)app.processEvents();
 if(delivered!=1){std::cerr<<"FAILED: cancelled calculations never reach the UI\n";return 1;}
 CalculationScheduler real;Json calculated;real.onResult=[&](const Json& value){calculated=value;};
 real.request({{"revision",4},{"sheets",Json::array({{{"id","s"},{"name","Sheet1"},{"cells",Json::array({{{"row",1},{"col",1},{"input","=2+3"}}})}}})}});deadline.restart();while(calculated.is_null()&&deadline.elapsed()<3000)app.processEvents();
 if(calculated.is_null()||calculated["revision"]!=4||calculated["values"][0]["value"]!=5){std::cerr<<"FAILED: worker calculates actual workbook formulas\n";return 1;}
}
